insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-note-001','Pharmacy','Diploma in Pharmacy','note','free',1,'{"title":"D.Pharm syllabus map: Pharmaceutics","english":"Pharmaceutics अध्ययनले dosage forms, prescription handling, weights and measures, pharmaceutical calculations, compounding, dispensing, packaging, storage र औषधिको stability समेट्छ। विद्यार्थीले tablets, capsules, liquids, semisolids, injections र अन्य dosage forms को विशेषता तथा सुरक्षित handling बुझ्नुपर्छ।","nepali":"Pharmaceutics मा औषधिका dosage form, prescription बुझ्ने तरिका, तौल र नाप, calculation, compounding, dispensing, packaging, storage र stability पढिन्छ। Tablet, capsule, liquid, semisolid र injection जस्ता dosage form को प्रयोग र सुरक्षित व्यवस्थापन बुझ्नुपर्छ।"}'::jsonb,true),
('dph-note-002','Pharmacy','Diploma in Pharmacy','note','free',2,'{"title":"D.Pharm syllabus map: Pharmaceutical Chemistry","english":"This area covers pharmaceutical substances, acids and bases, buffers, electrolytes, solutions, concentration expressions, titration principles, common inorganic agents and the chemistry, storage and quality assurance of selected medicines. Calculations and safe laboratory practice are important.","nepali":"यस भागमा pharmaceutical substances, acid-base, buffer, electrolyte, solution, concentration, titration, inorganic agents तथा औषधिको chemistry, storage र quality assurance पर्छन्। Calculation र laboratory safety पनि महत्त्वपूर्ण छन्।"}'::jsonb,true),
('dph-note-003','Pharmacy','Diploma in Pharmacy','note','trial',3,'{"title":"D.Pharm syllabus map: Pharmacology and Pharmacotherapeutics","english":"Study general pharmacology, routes of administration, pharmacokinetics, pharmacodynamics, adverse drug reactions and therapeutic use of medicines for gastrointestinal, respiratory, cardiovascular, nervous, endocrine and infectious conditions. Learn indications, contraindications, precautions and referral principles; do not treat a syllabus dose as an independent prescribing authority.","nepali":"General pharmacology, औषधि दिने मार्ग, pharmacokinetics, pharmacodynamics, adverse drug reaction तथा gastrointestinal, respiratory, cardiovascular, nervous, endocrine र infectious रोगमा औषधिको प्रयोग पढिन्छ। Indication, contraindication, सावधानी र referral बुझ्नुपर्छ; पाठ्यक्रममा भएको dose ले स्वतन्त्र prescribing अधिकार दिँदैन।"}'::jsonb,true),
('dph-note-004','Pharmacy','Diploma in Pharmacy','note','trial',4,'{"title":"D.Pharm syllabus map: Pharmacognosy","english":"Pharmacognosy focuses on crude drugs from natural sources, medicinal plant identification, collection, drying, storage, evaluation, adulteration, phytochemical groups and important medicinal plants found in Nepal. Scientific names, plant parts used and quality assessment are useful revision points.","nepali":"Pharmacognosy मा प्राकृतिक स्रोतका crude drugs, औषधीय वनस्पतिको पहिचान, संकलन, सुकाउने, भण्डारण, मूल्याङ्कन, adulteration, phytochemical समूह र नेपालका महत्त्वपूर्ण औषधीय वनस्पति पढिन्छन्। Botanical name, प्रयोग हुने भाग र quality assessment दोहोर्‍याउनुहोस्।"}'::jsonb,true),
('dph-note-005','Pharmacy','Diploma in Pharmacy','note','trial',5,'{"title":"D.Pharm syllabus map: Hospital and Community Pharmacy","english":"This area includes hospital and community pharmacy services, prescription dispensing, patient counselling, communication, pharmacy management, inventory control, procurement, storage, good pharmacy practice, clinical pharmacy, medication history, interactions and pharmacovigilance.","nepali":"यसमा hospital र community pharmacy सेवा, prescription dispensing, बिरामी परामर्श, communication, pharmacy management, inventory, procurement, storage, good pharmacy practice, clinical pharmacy, medication history, drug interaction र pharmacovigilance समेटिन्छन्।"}'::jsonb,true),
('dph-note-006','Pharmacy','Diploma in Pharmacy','note','trial',6,'{"title":"D.Pharm syllabus map: Social Pharmacy, Public Health and Law","english":"Study health concepts, primary health care, health education, Nepal''s health-care delivery system, public-health roles of pharmacy personnel, professional ethics and Nepalese pharmacy and drug laws. For legal questions, verify the currently applicable Act, Regulations and Department of Drug Administration notices.","nepali":"Health concept, primary health care, health education, नेपालको स्वास्थ्य सेवा प्रणाली, pharmacy personnel को public-health भूमिका, professional ethics तथा नेपालको pharmacy र drug laws पढ्नुहोस्। कानुनी विषयमा हाल लागू ऐन, नियमावली र औषधि व्यवस्था विभागका सूचना जाँच्नुहोस्।"}'::jsonb,true),
('bph-note-001','Pharmacy','Bachelor of Pharmacy','note','free',1,'{"title":"B.Pharm syllabus map: Pharmaceutical Analysis and Instrumentation","english":"This domain covers analytical principles, significant figures, errors, precision, accuracy, statistics, volumetric methods, titrations, chromatography and instrumental techniques such as UV-visible, IR, NMR, mass spectrometry and atomic absorption. Quality systems, validation and documentation are also included.","nepali":"यस क्षेत्रमा analytical principles, significant figures, error, precision, accuracy, statistics, volumetric methods, titration, chromatography र UV-visible, IR, NMR, mass spectrometry तथा atomic absorption जस्ता instrumental techniques पर्छन्। Quality systems, validation र documentation पनि समेटिन्छन्।"}'::jsonb,true),
('bph-note-002','Pharmacy','Bachelor of Pharmacy','note','free',2,'{"title":"B.Pharm syllabus map: Pharmaceutics, Technology and Biopharmaceutics","english":"Study preformulation, powder properties, solubility, stability, dosage-form design, manufacturing and quality control of solid, liquid, semisolid and parenteral products, packaging, GMP, QA, validation, dissolution, bioavailability and bioequivalence.","nepali":"Preformulation, powder properties, solubility, stability, dosage-form design, solid/liquid/semisolid/parenteral उत्पादनको manufacturing र quality control, packaging, GMP, QA, validation, dissolution, bioavailability र bioequivalence पढिन्छ।"}'::jsonb,true),
('bph-note-003','Pharmacy','Bachelor of Pharmacy','note','trial',3,'{"title":"B.Pharm syllabus map: Pharmacology and Therapeutics","english":"This domain includes pathophysiology and drug therapy across major body systems, pharmacokinetics, pharmacodynamics, antimicrobial chemotherapy, toxicology, adverse reactions, interactions, special populations, therapeutic drug monitoring and rational medicine use.","nepali":"यस क्षेत्रमा विभिन्न शरीर प्रणालीका रोगको pathophysiology र औषधि उपचार, pharmacokinetics, pharmacodynamics, antimicrobial chemotherapy, toxicology, adverse reaction, interaction, विशेष समूहका बिरामी, therapeutic drug monitoring र rational medicine use पर्छन्।"}'::jsonb,true),
('bph-note-004','Pharmacy','Bachelor of Pharmacy','note','trial',4,'{"title":"B.Pharm syllabus map: Pharmacognosy, Medicinal Chemistry and Natural Products","english":"Study drug discovery, physicochemical properties, biotransformation, prodrugs, clinical-trial phases, structure-activity relationships, natural sources, crude-drug evaluation, plant metabolites, extraction, isolation, purification and medicinally important natural products.","nepali":"Drug discovery, physicochemical properties, biotransformation, prodrug, clinical-trial phases, structure-activity relationship, प्राकृतिक स्रोत, crude-drug evaluation, plant metabolites, extraction, isolation, purification र औषधीय प्राकृतिक पदार्थ पढिन्छन्।"}'::jsonb,true),
('bph-note-005','Pharmacy','Bachelor of Pharmacy','note','trial',5,'{"title":"B.Pharm syllabus map: Clinical and Hospital Pharmacy","english":"This area covers hospital pharmacy organization, drug and therapeutic committees, formularies, drug information, inventory systems, inpatient and outpatient distribution, clinical assessment, medication history, ADRs, interactions, laboratory interpretation, special populations and referral.","nepali":"यस क्षेत्रमा hospital pharmacy organization, drug and therapeutic committee, formulary, drug information, inventory, inpatient/outpatient distribution, clinical assessment, medication history, ADR, interaction, laboratory interpretation, special population र referral पर्छन्।"}'::jsonb,true),
('bph-note-006','Pharmacy','Bachelor of Pharmacy','note','trial',6,'{"title":"B.Pharm syllabus map: Community, Social Pharmacy and Public Health","english":"Study good pharmacy practice, prescription handling, patient communication and counselling, primary health care, Nepal''s health system, public-health roles, pharmacy practice research, pharmacoepidemiology and pharmacoeconomics.","nepali":"Good pharmacy practice, prescription handling, बिरामीसँग communication र counselling, primary health care, नेपालको health system, public-health भूमिका, pharmacy practice research, pharmacoepidemiology र pharmacoeconomics पढिन्छन्।"}'::jsonb,true),
('bph-note-007','Pharmacy','Bachelor of Pharmacy','note','trial',7,'{"title":"B.Pharm syllabus map: Forensic Pharmacy, Law and Ethics","english":"This domain tests legal and professional pharmacy practice, including Nepal''s Drug Act and related regulations, Nepal Pharmacy Council Act, drug registration, manufacture, sale and distribution, controlled medicines, licensing, labelling, clinical trials, professional ethics and regulatory responsibilities.","nepali":"यस क्षेत्रमा नेपालको Drug Act तथा सम्बन्धित नियमावली, Nepal Pharmacy Council Act, औषधि दर्ता, उत्पादन, बिक्री-वितरण, नियन्त्रित औषधि, licensing, labelling, clinical trial, professional ethics र regulatory जिम्मेवारी पढिन्छन्।"}'::jsonb,true),
('dph-mcq-001','Pharmacy','Diploma in Pharmacy','mcq','trial',1,'{"question":"What is the main purpose of a disintegrant in a conventional tablet?","translation":"सामान्य tablet मा disintegrant को मुख्य काम के हो?","options":["To help the tablet break apart after administration","To add colour only","To prevent all dissolution","To act as the active drug"],"correctIndex":0,"explanation":"A disintegrant promotes tablet breakup into smaller particles, supporting drug dissolution.","explanationNe":"Disintegrant ले tablet लाई साना कणमा फुट्न मद्दत गर्छ, जसले औषधि घुल्न सहयोग गर्छ।"}'::jsonb,true),
('dph-mcq-002','Pharmacy','Diploma in Pharmacy','mcq','trial',2,'{"question":"Which record is essential when receiving a medicine stock?","translation":"औषधिको stock प्राप्त गर्दा कुन अभिलेख महत्त्वपूर्ण हुन्छ?","options":["Batch number and expiry date","Only carton colour","Only supplier''s logo","Only shelf number"],"correctIndex":0,"explanation":"Batch and expiry details support traceability, stock rotation and recall management.","explanationNe":"Batch र expiry विवरणले traceability, stock rotation र recall व्यवस्थापनमा सहयोग गर्छ।"}'::jsonb,true),
('dph-mcq-003','Pharmacy','Diploma in Pharmacy','mcq','trial',3,'{"question":"Which route generally avoids gastrointestinal absorption?","translation":"कुन route ले सामान्यतया gastrointestinal absorption टार्छ?","options":["Intravenous","Oral","Enteral tube","Rectal"],"correctIndex":0,"explanation":"Intravenous administration places the medicine directly into the circulation.","explanationNe":"Intravenous मार्गबाट औषधि सिधै रक्तसञ्चारमा पुग्छ।"}'::jsonb,true),
('dph-mcq-004','Pharmacy','Diploma in Pharmacy','mcq','trial',4,'{"question":"What does FEFO mean in pharmacy stock management?","translation":"Pharmacy stock management मा FEFO को अर्थ के हो?","options":["First Expiry, First Out","First Entry, First Order","Fast Entry, Fast Output","Final Expiry, Final Order"],"correctIndex":0,"explanation":"FEFO prioritizes items with the earliest expiry date for use or supply.","explanationNe":"FEFO मा सबैभन्दा पहिले म्याद सकिने औषधि पहिले प्रयोग वा वितरण गरिन्छ।"}'::jsonb,true),
('dph-mcq-005','Pharmacy','Diploma in Pharmacy','mcq','trial',5,'{"question":"Which professional action is appropriate when a prescription is unclear?","translation":"Prescription अस्पष्ट भएमा उपयुक्त professional कदम कुन हो?","options":["Clarify with the prescriber before dispensing","Guess the dose","Ignore the unclear part","Ask another customer"],"correctIndex":0,"explanation":"Unclear prescriptions must be clarified with the authorized prescriber before dispensing.","explanationNe":"अस्पष्ट prescription dispensing अघि अधिकृत prescriber सँग स्पष्ट गर्नुपर्छ।"}'::jsonb,true),
('dph-mcq-006','Pharmacy','Diploma in Pharmacy','mcq','trial',6,'{"question":"Which term describes an unwanted harmful response at normal medicine use?","translation":"औषधि सामान्य रूपमा प्रयोग गर्दा देखिने अनिच्छित हानिकारक प्रतिक्रियालाई के भनिन्छ?","options":["Adverse drug reaction","Therapeutic index","Bioavailability","Indication"],"correctIndex":0,"explanation":"An adverse drug reaction is a harmful and unintended response at normally used doses.","explanationNe":"सामान्य प्रयोगको मात्रामा देखिने हानिकारक र अनिच्छित प्रतिक्रियालाई adverse drug reaction भनिन्छ।"}'::jsonb,true),
('bph-mcq-001','Pharmacy','Bachelor of Pharmacy','mcq','trial',1,'{"question":"Which measure best describes closeness of repeated results to one another?","translation":"बारम्बार प्राप्त नतिजाहरू एक-अर्कासँग कति नजिक छन् भन्ने कुन मापनले जनाउँछ?","options":["Precision","Accuracy","Specificity","Sensitivity"],"correctIndex":0,"explanation":"Precision describes the agreement among repeated measurements.","explanationNe":"Precision ले दोहोरिएका मापनहरूबीचको समानता जनाउँछ।"}'::jsonb,true),
('bph-mcq-002','Pharmacy','Bachelor of Pharmacy','mcq','trial',2,'{"question":"Which chromatographic technique commonly uses a stationary layer on a plate?","translation":"Plate मा stationary layer प्रयोग गर्ने सामान्य chromatographic technique कुन हो?","options":["Thin-layer chromatography","Gas chromatography","Size-exclusion chromatography only","Ion-selective potentiometry"],"correctIndex":0,"explanation":"Thin-layer chromatography separates compounds on a coated plate.","explanationNe":"Thin-layer chromatography ले coating भएको plate मा पदार्थहरू छुट्याउँछ।"}'::jsonb,true),
('bph-mcq-003','Pharmacy','Bachelor of Pharmacy','mcq','trial',3,'{"question":"What does bioavailability describe?","translation":"Bioavailability ले के जनाउँछ?","options":["Rate and extent to which active drug reaches systemic circulation","Tablet hardness only","Drug colour","Shelf life only"],"correctIndex":0,"explanation":"Bioavailability describes the rate and extent of active drug reaching systemic circulation.","explanationNe":"Bioavailability ले सक्रिय औषधि systemic circulation मा पुग्ने दर र परिमाण जनाउँछ।"}'::jsonb,true),
('bph-mcq-004','Pharmacy','Bachelor of Pharmacy','mcq','trial',4,'{"question":"Which committee commonly oversees medicine selection and formulary decisions in a hospital?","translation":"Hospital मा औषधि छनोट र formulary निर्णयमा कुन committee संलग्न हुन्छ?","options":["Drug and Therapeutics Committee","Ethics committee only","Building committee","Transport committee"],"correctIndex":0,"explanation":"A Drug and Therapeutics Committee supports evidence-based medicine selection and use.","explanationNe":"Drug and Therapeutics Committee ले प्रमाणमा आधारित औषधि छनोट र प्रयोगमा सहयोग गर्छ।"}'::jsonb,true),
('bph-mcq-005','Pharmacy','Bachelor of Pharmacy','mcq','trial',5,'{"question":"Which process confirms that an analytical method is suitable for its intended purpose?","translation":"Analytical method आफ्नो उद्देश्यका लागि उपयुक्त छ भनी प्रमाणित गर्ने प्रक्रिया कुन हो?","options":["Method validation","Randomization","Maceration","Disintegration"],"correctIndex":0,"explanation":"Method validation provides documented evidence that an analytical procedure is fit for purpose.","explanationNe":"Method validation ले analytical procedure आफ्नो उद्देश्यका लागि उपयुक्त छ भन्ने अभिलेखित प्रमाण दिन्छ।"}'::jsonb,true),
('bph-mcq-006','Pharmacy','Bachelor of Pharmacy','mcq','trial',6,'{"question":"Which pharmacokinetic parameter is commonly used to describe the apparent volume relating drug amount in the body to plasma concentration?","translation":"शरीरमा औषधिको मात्रा र plasma concentration बीचको सम्बन्ध जनाउने pharmacokinetic parameter कुन हो?","options":["Volume of distribution","Clearance","Half-life only","AUC"],"correctIndex":0,"explanation":"Volume of distribution relates the amount of drug in the body to its plasma concentration.","explanationNe":"Volume of distribution ले शरीरमा औषधिको मात्रा र plasma concentration बीचको सम्बन्ध जनाउँछ।"}'::jsonb,true)
