-- Pharmacy faculties: Phase 1 syllabus map and starter practice bank
-- Based on the current NPC Diploma and Bachelor Name Registration syllabi.
-- Run after supabase/secure-content.sql. Safe to re-run: content_id is unique.
on conflict (content_id) do update set
  faculty=excluded.faculty,
  subject=excluded.subject,
  content_type=excluded.content_type,
  access_tier=excluded.access_tier,
  display_order=excluded.display_order,
  content_data=excluded.content_data,
  is_published=excluded.is_published,
  updated_at=now();
